namespace RecipeSharing.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeCategory
{
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public string Icon { get; set; } = string.Empty;
}

using RecipeSharing.Models;

namespace RecipeSharing.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly List<RecipeCategory> _categories;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Name = "Breakfast", Description = "Start your day right with these morning favorites", Icon = "🥞" },
            new() { Name = "Lunch", Description = "Quick and satisfying midday meals", Icon = "🥗" },
            new() { Name = "Dinner", Description = "Hearty evening dishes for the whole family", Icon = "🍝" },
            new() { Name = "Desserts", Description = "Sweet treats to end any meal", Icon = "🍰" },
            new() { Name = "Snacks", Description = "Light bites for any time of day", Icon = "🍿" },
            new() { Name = "Drinks", Description = "Refreshing beverages and smoothies", Icon = "🥤" }
        };

        _recipes = new List<Recipe>
        {
            new() { Id = 1, Title = "Classic Pancakes", Category = "Breakfast", Ingredients = "2 cups flour
2 eggs
1.5 cups milk
2 tbsp sugar
1 tsp baking powder
Butter for cooking", Steps = "1. Mix dry ingredients in a bowl.
2. Whisk eggs and milk together.
3. Combine wet and dry ingredients until just mixed.
4. Heat a buttered pan over medium heat.
5. Pour 1/4 cup batter per pancake.
6. Flip when bubbles form on surface.
7. Cook until golden brown.", AverageRating = 4.5, RatingCount = 12 },
            new() { Id = 2, Title = "Caesar Salad", Category = "Lunch", Ingredients = "1 head romaine lettuce
1/2 cup croutons
1/4 cup parmesan cheese
Caesar dressing
Grilled chicken (optional)", Steps = "1. Wash and chop romaine lettuce.
2. Toss with Caesar dressing.
3. Top with croutons and shaved parmesan.
4. Add grilled chicken if desired.
5. Serve immediately.", AverageRating = 4.2, RatingCount = 8 },
            new() { Id = 3, Title = "Spaghetti Bolognese", Category = "Dinner", Ingredients = "400g spaghetti
500g ground beef
1 onion, diced
3 cloves garlic
800g canned tomatoes
2 tbsp tomato paste
Basil, oregano, salt, pepper", Steps = "1. Cook spaghetti according to package directions.
2. Brown ground beef in a large pan.
3. Add diced onion and garlic, cook until soft.
4. Stir in canned tomatoes and tomato paste.
5. Season with herbs, salt, and pepper.
6. Simmer for 20 minutes.
7. Serve sauce over drained pasta.", AverageRating = 4.8, RatingCount = 25 },
            new() { Id = 4, Title = "Chocolate Chip Cookies", Category = "Desserts", Ingredients = "2.25 cups flour
1 cup butter, softened
3/4 cup sugar
3/4 cup brown sugar
2 eggs
1 tsp vanilla
1 tsp baking soda
2 cups chocolate chips", Steps = "1. Preheat oven to 375°F (190°C).
2. Cream butter and sugars together.
3. Beat in eggs and vanilla.
4. Mix in flour and baking soda.
5. Fold in chocolate chips.
6. Drop spoonfuls onto baking sheet.
7. Bake 9-11 minutes until golden.", AverageRating = 4.9, RatingCount = 30 },
            new() { Id = 5, Title = "Guacamole", Category = "Snacks", Ingredients = "3 ripe avocados
1 lime, juiced
1 tsp salt
1/2 cup onion, diced
3 tbsp cilantro
2 roma tomatoes, diced
1 tsp garlic, minced
1 pinch cayenne pepper", Steps = "1. Cut avocados in half and remove pit.
2. Scoop out flesh and mash with a fork.
3. Stir in lime juice and salt.
4. Mix in onion, cilantro, tomatoes, and garlic.
5. Add cayenne pepper to taste.
6. Serve with tortilla chips.", AverageRating = 4.6, RatingCount = 15 },
            new() { Id = 6, Title = "Berry Smoothie", Category = "Drinks", Ingredients = "1 cup mixed berries
1 banana
1 cup yogurt
1/2 cup milk
1 tbsp honey
Ice cubes", Steps = "1. Add all ingredients to blender.
2. Blend until smooth.
3. Add more milk if too thick.
4. Pour into glass and serve immediately.", AverageRating = 4.3, RatingCount = 10 }
        };
    }

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }
}

