@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0"
              style="cursor: pointer; font-size: 1.5rem; color: @(star <= (_hoverRating > 0 ? _hoverRating : _selectedRating) ? "#ffc107" : "#e0e0e0")">
            ★
        </span>
    }
    @if (_submitted)
    {
        <span class="ms-2 text-success">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    [Inject] private Services.RecipeService RecipeService { get; set; } = default!;

    private int _selectedRating;
    private int _hoverRating;
    private bool _submitted;

    protected override void OnParametersSet()
    {
        _selectedRating = (int)Math.Round(CurrentRating);
    }

    private async Task Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _submitted = true;
        await OnRated.InvokeAsync(stars);
    }
}

@page "/category/{CategoryName}"
@using RecipeSharing.Services
@inject RecipeService RecipeService

<PageTitle>@CategoryName Recipes</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (_recipes.Any())
    {
        <div class="row g-4">
            @foreach (var recipe in _recipes)
            {
                <div class="col-md-6">
                    <div class="card shadow-sm">
                        <div class="card-body">
                            <h5 class="card-title">@recipe.Title</h5>
                            <p class="text-muted mb-2">
                                ⭐ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
    else
    {
        <div class="alert alert-info">No recipes found in this category yet. <a href="/submit">Be the first to submit one!</a></div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
    private List<RecipeSharing.Models.Recipe> _recipes = new();

    protected override void OnParametersSet()
    {
        _recipes = RecipeService.GetRecipesByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeSharing.Services
@using RecipeSharing.Components.Shared
@inject RecipeService RecipeService

<PageTitle>@(_recipe?.Title ?? "Recipe")</PageTitle>

<div class="container py-4">
    @if (_recipe is null)
    {
        <div class="alert alert-warning">Recipe not found.</div>
    }
    else
    {
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/">Home</a></li>
                <li class="breadcrumb-item"><a href="/category/@_recipe.Category.ToLower()">@_recipe.Category</a></li>
                <li class="breadcrumb-item active">@_recipe.Title</li>
            </ol>
        </nav>

        <h1 class="mb-2">@_recipe.Title</h1>
        <p class="text-muted">Category: @_recipe.Category</p>

        <div class="mb-4">
            <h5>Rate this recipe:</h5>
            <StarRating RecipeId="@_recipe.Id"
                        CurrentRating="@_recipe.AverageRating"
                        RatingCount="@_recipe.RatingCount" />
            <small class="text-muted d-block mt-1">
                @_recipe.AverageRating.ToString("F1") average from @_recipe.RatingCount ratings
            </small>
        </div>

        <div class="row">
            <div class="col-md-5">
                <div class="card mb-4">
                    <div class="card-header bg-success text-white">
                        <h5 class="mb-0">🥕 Ingredients</h5>
                    </div>
                    <div class="card-body">
                        <ul class="list-unstyled mb-0">
                            @foreach (var ingredient in _recipe.Ingredients.Split('\n'))
                            {
                                <li class="mb-1">• @ingredient</li>
                            }
                        </ul>
                    </div>
                </div>
            </div>
            <div class="col-md-7">
                <div class="card mb-4">
                    <div class="card-header bg-primary text-white">
                        <h5 class="mb-0">📋 Steps</h5>
                    </div>
                    <div class="card-body">
                        @foreach (var step in _recipe.Steps.Split('\n'))
                        {
                            <p class="mb-2">@step</p>
                        }
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }
    private RecipeSharing.Models.Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeSharing.Models
@using RecipeSharing.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit Your Recipe</h1>

    @if (_submitted)
    {
        <div class="alert alert-success">
            <h4>Recipe submitted successfully!</h4>
            <p>Your recipe "@_model.Title" has been added to the community.</p>
            <a href="/" class="btn btn-primary">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />
            <ValidationSummary class="text-danger" />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                    <option value="">-- Select a category --</option>
                    @foreach (var cat in RecipeService.GetCategories())
                    {
                        <option value="@cat.Name">@cat.Name</option>
                    }
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="_model.Ingredients" placeholder="One ingredient per line" />
                <div class="form-text">Enter one ingredient per line.</div>
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps</label>
                <InputTextArea id="steps" class="form-control" rows="8" @bind-Value="_model.Steps" placeholder="1. First step&#10;2. Second step&#10;3. Third step" />
                <div class="form-text">Number each step for clarity.</div>
            </div>

            <button type="submit" class="btn btn-primary btn-lg">Submit Recipe</button>
        </EditForm>
    }
</div>

@code {
    private Recipe _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        if (!string.IsNullOrWhiteSpace(_model.Title) &&
            !string.IsNullOrWhiteSpace(_model.Category) &&
            !string.IsNullOrWhiteSpace(_model.Ingredients) &&
            !string.IsNullOrWhiteSpace(_model.Steps))
        {
            RecipeService.AddRecipe(_model);
            _submitted = true;
        }
    }
}

